ate delivery quality and transparency.\",\"manual_review_required\":false,\"manual_review_reason_type\":null,\"manual_review_reason\":null,\"chapter_specific\":[{\"field\":\"program_basis\",\"value\":\"mixed\"},{\"field\":\"program_type\",\"value\":\"policy, regime_control, state_building\"},{\"field\":\"strategic_clarity\",\"value\":\"clear\"},{\"field\":\"operationalization\",\"value\":\"mixed\"},{\"field\":\"goal_progress\",\"value\":\"mixed\"},{\"field\":\"durability\",\"value\":\"mixed\"}]},{\"dossier_job_key\":\"dossier:2022-top20-hybrid-v2:2022:ETH:16782\",\"iso3\":\"ETH\",\"ruler_id\":\"2310\",\"ruler_year_id\":16782,\"ruler_name\":\"Abiy Ahmed\",\"period_start_year\":2022,\"period_end_year\":2022,\"chapter_id\":\"8B\",\"rubric_version\":\"chapter_8b_v3\",\"calibration_batch_id\":\"chapter-judge:2022-saturation-v3-stage1-controlled:2022:8B\",\"calibrated_against\":[\"dossier:2022-top20-hybrid-v2:2022:DEU:16984\",\"dossier:2022-top20-hybrid-v2:2022:USA:15810\",\"dossier:2022-top20-hybrid-v2:2022:RUS:15706\"],\"score_1_to_10\":6,\"insufficient_evidence_reason\":null,\"confidence_score\":68,\"plausible_score_range\":{\"lower\":5.5,\"upper\":6.5},\"decisive_positive_evidence\":[{\"evidence_id\":\"E0089\",\"explanation\":\"Ceasefire access and aid movement show real post-conflict execution.\"},{\"evidence_id\":\"E0092\",\"explanation\":\"Restored services in Tigray show concrete state reach.\"}],\"decisive_negative_evidence\":[{\"evidence_id\":\"E0041\",\"explanation\":\"Dialogue process was contested and exclusionary.\"},{\"evidence_id\":\"E0090\",\"explanation\":\"Implementation was still a promise rather than an audit.\"}],\"inherited_baseline_and_constraints\":\"Weak state, civil conflict, and limited administrative capacity.\",\"ruler_attribution\":\"Some direct leadership and state mobilization, but delivery is heavily partner-mediated and only partially complete.\",\"supported_lenses\":[\"8B.2\",\"8B.3\",\"8B.5\",\"8B.6\",\"8B.8\",\"8B.9\",\"8B.10\"],\"mis